from collections import defaultdict

from taf.ul.bts_kpi_report_generator.converter.DoubleAsteriskError import DoubleAsteriskError
from taf.ul.bts_kpi_report_generator.converter.UnintendedPhraseError import UnintendedPhraseError
from taf.ul.bts_kpi_report_generator.converter.WrongBracketsEnclosureError import WrongBracketsEnclosureError


class KPIErrorsHandler:
    """
    Main class for handling KPI's errors .
    """

    def __init__(self, source_file_path, release):
        self.double_asterix_error_handler = DoubleAsteriskError(source_file_path, release)
        self.unintended_phrase_error_handler = UnintendedPhraseError(source_file_path, release)
        self.wrong_brackets_enclosure_error_handler = WrongBracketsEnclosureError(source_file_path, release)

    @staticmethod
    def fix_uncommon_categories_bugs(nested_array):
        """
        Fix errors which are unusual and inimitable, such erros are required to be
        managed individually, e.g. typos in categories, inconsistent data type of the same information
        about KPI

        :return: None
        """
        if type(nested_array[-1]) is str:
            if nested_array[-1] == "Accessssibility":
                nested_array[-1] = "Accessibility"

            nested_array[-1] = nested_array[-1].replace(" ", "")
            slash_index = nested_array[-1].find('/')
            if slash_index >= 0:
                nested_array.append((nested_array[-1])[slash_index + 1:])
                nested_array[-2] = (nested_array[-2])[:slash_index]

        if not nested_array[-1]:
            nested_array[-1] = "Others"

        return nested_array

    def update_errors_storage(self, kpi_id):
        """
        Checks if any errors were found during KPI's parsing,
        if yes then such KPI is added into KPI with errors storage

        :return: None
        """
        if len(self.unintended_phrase_error_handler.found_errors):
            self.unintended_phrase_error_handler.KPIs_with_errors.update({kpi_id: self.unintended_phrase_error_handler.found_errors})
        if len(self.double_asterix_error_handler.found_errors):
            self.double_asterix_error_handler.KPIs_with_errors.update({kpi_id: self.double_asterix_error_handler.found_errors})
        if len(self.wrong_brackets_enclosure_error_handler.found_errors):
            self.wrong_brackets_enclosure_error_handler.KPIs_with_errors.update({kpi_id: self.wrong_brackets_enclosure_error_handler.found_errors})

    def update_kpi_errors_info(self, nested):
        """
         Updates data KPI with information about errors
         associated to it .

         :return: Dictionary with updated KPI data
         """
        if self.unintended_phrase_error_handler.found_errors:
            concatenated_errors = self.concatenate_errors()
            nested.update({"ERRORS": concatenated_errors})
        return nested

    def check_errors_and_warn(self):
        """
        Checks if any KPI's error occurred,
        if yes, warns user about adding
        release file into repository

        :return: None
        """
        if (self.double_asterix_error_handler.KPIs_with_errors or self.wrong_brackets_enclosure_error_handler.KPIs_with_errors
                or self.unintended_phrase_error_handler.KPIs_with_errors):
            print("KPI's with errors has been found, adding newly created file into repository should be sensibly considered")

    def check_for_duplicates(self, kpi_id, parsed):
        """
        Checks if KPI is not duplicated in source xml file,
        that is, checks if there are KPI's with the same ID

        :return: None
        """
        if kpi_id in parsed or kpi_id in self.unintended_phrase_error_handler.filtered_kpis:
            if not any("Found duplicated" in error for error in self.unintended_phrase_error_handler.found_errors):
                self.double_asterix_error_handler.ErrorsPrinter.warn_print("Found duplicated KPI", kpi_id)
                self.unintended_phrase_error_handler.found_errors.append(
                    "Duplicated KPI (Database has KPI's with the same "
                    "ID thus informations about such KPI is ambiguous)")

    def check_for_critical_errors(self):
        """
        Checks if any KPI's counters from formula are not included in
        it's dependencies .

        :return: None
        """
        if any("Suspicious counter" in error for error in self.unintended_phrase_error_handler.found_errors)\
                or any("Unusual phrases" in error for error in self.unintended_phrase_error_handler.found_errors):
            return True
        return False

    def update_lacking_dependencies(self, dependencies, counters_from_formula, kpi_id, nested):
        """
        If any KPI's counters from formula are not included in
        it's dependencies, function tries to fill them by lacking ones .

        :param dependencies: kpi's dependencies
        :param counters_from_formula: kpi's counters used in it's formula
        :param kpi_id: analyzed kpi ID
        :param nested: analyzed kpi's data

        :return: nested dictionary after update by lacking counters in dependencies
        """

        union_of_dependencies = counters_from_formula.union(dependencies)
        nested.update({"DEPENDENCIES": dict.fromkeys(union_of_dependencies, "")})
        self.unintended_phrase_error_handler.ErrorsPrinter.info_print("KPI updated by lacking dependencies", "{} : {}".format(
            kpi_id,
            counters_from_formula.difference(dependencies)
        ))
        self.unintended_phrase_error_handler.logger.info("KPI updated by lacking dependencies {} : {}".format(kpi_id,
                                                         counters_from_formula.difference(dependencies)))
        return nested

    def concatenate_kpis_with_errors(self):
        """
        Takes every kpi with any occurrence of error and concatenate it into one
        storage

        :return: every kpi containing any error
        """

        concacenated_kpis_with_errors = defaultdict(list)
        try:
            for d in (self.unintended_phrase_error_handler.KPIs_with_errors, self.wrong_brackets_enclosure_error_handler.KPIs_with_errors,
                      self.double_asterix_error_handler.KPIs_with_errors):
                for key, value in d.items():
                    concacenated_kpis_with_errors[key].extend(value)
        except Exception as exc:
            print("{} occured when trying to save {}"
                  "into errors data file".format(exc, value))
            self.unintended_phrase_error_handler.logger.warning("{} occured when trying to save {}"
                                                                "into errors data file".format(exc, value))

        return dict(concacenated_kpis_with_errors)

    def concatenate_errors(self):
        """
        Takes every error occurred and concatenate it into one
        storage

        :return: every occurred error
        """
        concatenate_errors = list()
        if self.unintended_phrase_error_handler.found_errors:
            concatenate_errors.extend(self.unintended_phrase_error_handler.found_errors)
        if self.wrong_brackets_enclosure_error_handler.found_errors:
            concatenate_errors.extend(self.wrong_brackets_enclosure_error_handler.found_errors)
        if self.double_asterix_error_handler.found_errors:
            concatenate_errors.extend(self.double_asterix_error_handler.found_errors)
        return concatenate_errors

    def clear_errors(self):
        """
        Buffer, evacuates errors storage

        :return: None
        """
        self.unintended_phrase_error_handler.found_errors = []
        self.wrong_brackets_enclosure_error_handler.found_errors = []
        self.double_asterix_error_handler.found_errors = []

    def filter_kpi(self, kpi_id, parsed):
        """
        Perform's kpi filtering operations

        :param kpi_id: ID of kpi being filtered
        :param parsed: main kpi data storage

        :return: None
        """
        self.unintended_phrase_error_handler.logger.info(
            "KPI has been filtered {}".format(kpi_id))
        self.unintended_phrase_error_handler.ErrorsPrinter.info_print("KPI has been filtered", kpi_id)
        self.check_for_duplicates(kpi_id, parsed)
        self.unintended_phrase_error_handler.filtered_kpis.append(kpi_id)
